// usage: node drv.mjs <casefile.json>
// casefile.json = array of [lang, code] pairs  (lang '' => bare fence)
import { phase } from '/tmp/probe/p.mjs';
import { readFileSync } from 'node:fs';
const cases = JSON.parse(readFileSync(process.argv[2], 'utf8'));
const FENCE = '`'.repeat(6);
const doc = cases.map(([lang, code]) => FENCE + lang + '\n' + code + '\n' + FENCE).join('\n\n');
const out = phase('e', doc);
// split on codehilite blocks
const re = /<div class="codehilite"><pre><span><\/span><code>([\s\S]*?)<\/code><\/pre><\/div>/g;
const blocks = [];
let m;
while ((m = re.exec(out)) !== null) blocks.push(m[1]);
if (blocks.length !== cases.length) {
  console.log('!!! MISMATCH blocks=' + blocks.length + ' cases=' + cases.length);
  console.log('RAWOUT=' + JSON.stringify(out).slice(0, 4000));
}
for (let i = 0; i < cases.length; i++) {
  console.log('### [' + cases[i][0] + '] IN=' + JSON.stringify(cases[i][1]));
  console.log('    OUT=' + JSON.stringify(blocks[i]));
}
EOF
